def _page(title,chapter,point,accent,label):
    t,c,p=map(html.escape,(title,chapter,point)); related='关系' in label; mode="'space'" if related else "'solid'"
    toggles='<div class="group"><b>线线</b><button data-rel="ll-intersect">相交</button><button data-rel="ll-parallel">平行</button><button data-rel="ll-skew">异面</button></div><div class="group"><b>线面</b><button data-rel="lm-intersect">相交</button><button data-rel="lm-perp">垂直</button><button data-rel="lm-parallel">平行</button><button data-rel="lm-contained">线在面内</button></div><div class="group"><b>面面</b><button data-rel="pp-intersect">相交</button><button data-rel="pp-perp">垂直</button><button data-rel="pp-parallel">平行</button></div>' if related else '<button data-shape="cube">正方体</button><button data-shape="cylinder">圆柱体</button>'
    move_controls='' ; q='相邻棱与相对面分别是什么关系？' if related else '正方体有几个面、几条棱、几个顶点？'; a='相邻棱相交且垂直；相对的面互相平行。' if related else '正方体有6个面、12条棱、8个顶点；圆柱体侧面是曲面。'; legend='<div id="legend" class="legend"></div>' if related else '<div class="legend"><span>实体表面</span><span>深色轮廓：棱</span><span>转动可观察背面</span></div>'
    return f'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{t}</title><style>:root{{--a:{accent};--ink:#203548}}*{{box-sizing:border-box}}body{{margin:0;background:#f3f8fb;color:var(--ink);font:16px/1.6 system-ui,"Microsoft Yahei",sans-serif}}main{{max-width:960px;margin:auto;padding:28px 20px}}section{{background:#fff;border:1px solid #dbe6ed;border-radius:22px;padding:24px;box-shadow:0 14px 40px #23405b16;margin-bottom:18px}}.tag{{color:var(--a);font-weight:700}}.board{{margin-top:16px;padding:18px;background:#fbfdff;border:1px solid #dbe6ed;border-radius:15px}}button{{border:0;border-radius:9px;background:var(--a);color:#fff;padding:9px 14px;margin:3px;cursor:pointer}}button.active{{outline:3px solid #315f8c33}}.group{{display:inline-flex;align-items:center;gap:3px;margin:3px 8px 8px 0}}.group b{{font-size:12px;color:#536b7d}}.move-controls{{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:5px 0 10px;color:#536b7d;font-size:13px}}.sliders{{display:flex;gap:8px;flex-wrap:wrap;font-size:12px;color:#536b7d}}.sliders input{{width:100px;min-height:28px;touch-action:manipulation}}.legend{{display:flex;gap:14px;flex-wrap:wrap;margin:5px 0 10px;color:#536b7d;font-size:13px}}.l1{{color:#d66c62}}.l2{{color:#2878c8}}canvas{{display:block;user-select:none;-webkit-user-select:none;width:100%;height:380px;background:linear-gradient(145deg,#f8fcff,#edf5f8);border:1px solid #dbe6ed;border-radius:13px;touch-action:none;cursor:grab}}.webgl-fallback{{display:grid;place-items:center;height:380px;border:1px solid #dbe6ed;border-radius:13px;background:#f8fbfd;color:#627789}}canvas.is-dragging{{cursor:grabbing;filter:drop-shadow(0 6px 8px #315f8c55)}}#o{{color:#627789;font-size:13px}}.answer{{color:#27654d;background:#edf8f2;border-radius:9px;padding:11px}}@media(max-width:680px){{canvas{{height:300px}}}}@media(prefers-reduced-motion:reduce){{*{{transition:none!important}}}}</style><main><section><div class="tag">{c} · {p}</div><h1>{t}</h1><p>观察 {html.escape(label)}，用真实三维视角理解空间关系。</p></section><section><p>操作提示：长按图形或空白区域后拖动；也可用方向键精细调整视角。</p><div class="board">{toggles}{legend}<button id="lock">锁定视角</button><button id="reset">重置视角</button><canvas id="s" role="img" aria-label="{html.escape(label)}"></canvas><div id="o"></div><button id="guess">先猜一下</button><button id="show">显示规律</button><p id="a" class="answer" aria-live="polite"></p></div><div class="board"><strong>小练习</strong><p>{q}</p><details><summary>显示答案</summary><p class="answer">{a}</p></details></div></section></main><script>/* {THREE_LICENSE} */
{THREE_LIB}</script><script>{SCRIPT.replace('mode=__MODE__','mode='+mode)}</script></html>'''

def build_solid_html(title,chapter,point,accent): return _page(title,chapter,point,accent,'正方体与圆柱体')
def build_space_relations_html(title,chapter,point,accent): return _page(title,chapter,point,accent,'线线、线面、面面关系')

def build_views_html(title, chapter, point, accent):
    """Build a 3D cuboid scene for front/top/left views.

    The dimensions start at length=3, height=2, width=1 so each view has
    an unambiguous rectangle and a checkable area relationship.
    """
    t, c, p = map(html.escape, (title, chapter, point))
    script = r"""
const canvas=document.getElementById('s'),out=document.getElementById('o'),answer=document.getElementById('a'),reset=document.getElementById('reset');
let view='front',yaw=0,pitch=.24,dragging=false,pressTimer=null,pending=null,last=null;
const renderer=new THREE.WebGLRenderer({canvas,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0xf5fafc);
const scene=new THREE.Scene(),camera=new THREE.OrthographicCamera(-4,4,3,-3,.1,100),model=new THREE.Group();scene.add(model);
scene.add(new THREE.HemisphereLight(0xffffff,0x778899,2));const light=new THREE.DirectionalLight(0xffffff,2.7);light.position.set(4,6,5);scene.add(light);
const dims={length:3,height:2,width:1};
function make(){while(model.children.length){const obj=model.children[0];model.remove(obj);obj.traverse(x=>{x.geometry?.dispose();x.material?.dispose()})}const mesh=new THREE.Mesh(new THREE.BoxGeometry(dims.length,dims.height,dims.width),new THREE.MeshStandardMaterial({color:0x78aeb0,roughness:.5}));model.add(mesh);const edge=new THREE.LineSegments(new THREE.EdgesGeometry(mesh.geometry),new THREE.LineBasicMaterial({color:0x315e67}));mesh.add(edge);}
function setView(next){view=next;if(next==='front'){yaw=0;pitch=0;}else if(next==='top'){yaw=0;pitch=Math.PI/2;}else{yaw=-Math.PI/2;pitch=0;}document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));draw();}
function draw(){const w=canvas.clientWidth,h=canvas.clientHeight;renderer.setSize(w,h,false);const half=Math.max(dims.length,dims.width,dims.height)*.85+1;camera.left=-half*w/h;camera.right=half*w/h;camera.top=half;camera.bottom=-half;camera.up.set(0,1,0);if(view==='front')camera.position.set(0,0,20);else if(view==='top'){camera.position.set(0,20,0);camera.up.set(0,0,-1);}else if(view==='left')camera.position.set(-20,0,0);else camera.position.set(20*Math.sin(yaw)*Math.cos(pitch),20*Math.sin(pitch),20*Math.cos(yaw)*Math.cos(pitch));camera.lookAt(0,0,0);camera.updateProjectionMatrix();renderer.render(scene,camera);const info=view==='front'?`正视图：长 × 高 = ${dims.length} × ${dims.height}`:view==='top'?`俯视图：长 × 宽 = ${dims.length} × ${dims.width}`:view==='left'?`左视图：宽 × 高 = ${dims.width} × ${dims.height}`:'自由观察：当前角度不是标准三视图';out.textContent=info+`；正视图面积 ${dims.length*dims.height}，俯视图面积 ${dims.length*dims.width}，左视图面积 ${dims.width*dims.height}（平方单位）。`;document.querySelectorAll('[data-dimension]').forEach(input=>{input.value=dims[input.dataset.dimension];document.getElementById(input.dataset.dimension+'Value').textContent=input.value});}
canvas.onpointerdown=e=>{clearTimeout(pressTimer);pending=e;pressTimer=setTimeout(()=>{if(!pending)return;dragging=true;last=[pending.clientX,pending.clientY];canvas.setPointerCapture?.(pending.pointerId);canvas.classList.add('is-dragging');pending=null;},350)};
canvas.onpointermove=e=>{if(!dragging)return;view='free';document.querySelectorAll('[data-view]').forEach(b=>b.classList.remove('active'));yaw-=(e.clientX-last[0])*.009;pitch=Math.max(-1.2,Math.min(1.45,pitch+(e.clientY-last[1])*.009));last=[e.clientX,e.clientY];draw()};
canvas.onpointerup=canvas.onpointercancel=canvas.onpointerleave=()=>{clearTimeout(pressTimer);pressTimer=null;pending=null;dragging=false;canvas.classList.remove('is-dragging')};
canvas.tabIndex=0;canvas.onkeydown=e=>{if(e.key==='ArrowLeft')yaw+=.08;else if(e.key==='ArrowRight')yaw-=.08;else if(e.key==='ArrowUp')pitch=Math.min(1.45,pitch+.08);else if(e.key==='ArrowDown')pitch=Math.max(-1.2,pitch-.08);else return;e.preventDefault();view='free';document.querySelectorAll('[data-view]').forEach(b=>b.classList.remove('active'));draw()};
document.querySelectorAll('[data-dimension]').forEach(input=>input.oninput=()=>{dims[input.dataset.dimension]=Number(input.value);make();draw()});window.addEventListener('resize',draw);
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));document.getElementById('guess').onclick=()=>answer.textContent='先猜一猜：长方体从正面、上面、左面看到的长方形边长分别对应哪两条棱？';document.getElementById('show').onclick=()=>answer.textContent='正视图看长×高，俯视图看长×宽，左视图看宽×高；同一个长方体的三个视图共享这三条棱长。';reset.onclick=()=>{Object.assign(dims,{length:3,width:1,height:2});make();setView('front');answer.textContent='已重置到长 3、宽 1、高 2 的正视图。'};make();setView('front');
"""
    return f'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{t}</title><style>:root{{--a:{accent};--ink:#203548}}*{{box-sizing:border-box}}body{{margin:0;background:#f3f8fb;color:var(--ink);font:16px/1.6 system-ui,"Microsoft Yahei",sans-serif}}main{{max-width:960px;margin:auto;padding:28px 20px}}section{{background:#fff;border:1px solid #dbe6ed;border-radius:22px;padding:24px;box-shadow:0 14px 40px #23405b16;margin-bottom:18px}}.tag{{color:var(--a);font-weight:700}}.board{{margin-top:16px;padding:18px;background:#fbfdff;border:1px solid #dbe6ed;border-radius:15px}}.dimension-controls{{display:flex;flex-wrap:wrap;gap:10px 18px;align-items:center;margin-bottom:8px}}label{{display:inline-flex;align-items:center;gap:6px;color:#40576a;font-weight:600}}input{{accent-color:var(--a);min-width:130px}}button{{border:0;border-radius:9px;background:var(--a);color:#fff;padding:9px 14px;margin:3px;cursor:pointer}}button.active{{outline:3px solid #315f8c33}}canvas{{display:block;user-select:none;-webkit-user-select:none;width:100%;height:380px;background:linear-gradient(145deg,#f8fcff,#edf5f8);border:1px solid #dbe6ed;border-radius:13px;touch-action:none;cursor:grab}}canvas.is-dragging{{cursor:grabbing}}#o{{color:#627789;font-size:13px}}.answer{{color:#27654d;background:#edf8f2;border-radius:9px;padding:11px}}@media(max-width:680px){{canvas{{height:300px}}.dimension-controls{{display:grid;grid-template-columns:1fr}}}}@media(prefers-reduced-motion:reduce){{*{{transition:none!important}}}}</style><main><section><div class="tag">{c} · {p}</div><h1>{t}</h1><p>用一个长方体和真实三维视角理解三视图。</p></section><section><p>操作提示：点击正视图、俯视图或左视图切换观察方向；长按模型后拖动旋转，也可用方向键。</p><div class="board"><div class="dimension-controls"><label>长 <input data-dimension="length" type="range" min="1" max="6" value="3"><output id="lengthValue">3</output></label><label>宽 <input data-dimension="width" type="range" min="1" max="6" value="1"><output id="widthValue">1</output></label><label>高 <input data-dimension="height" type="range" min="1" max="6" value="2"><output id="heightValue">2</output></label></div><button data-view="front">正视图</button><button data-view="top">俯视图</button><button data-view="left">左视图</button><button id="reset">重置视角</button><canvas id="s" role="img" aria-label="长方体三视图"></canvas><div id="o"></div><button id="guess">先猜一下</button><button id="show">显示规律</button><p id="a" class="answer" aria-live="polite"></p></div><div class="board"><strong>小练习</strong><p>长方体长 3、宽 1、高 2，正视图、俯视图、左视图的面积分别是多少？</p><details><summary>显示答案</summary><p class="answer" aria-live="polite">正视图 3×2=6，俯视图 3×1=3，左视图 1×2=2（平方单位）。</p></details></div></section></main><script>/* {THREE_LICENSE} */
{THREE_LIB}</script><script>{script}</script></html>'''
